// Index of the two hole cards' class in kPreflopRanked.
inline int pushfoldClassIndex(const Card &a, const Card &b) {
    int hi = static_cast<int>(a.rank), lo = static_cast<int>(b.rank);
    if (hi < lo) { int t = hi; hi = lo; lo = t; }
    const bool suited = a.suit == b.suit;
    for (int i = 0; i < 169; ++i) {
        const PreflopClass &c = kPreflopRanked[i];
        if (c.high == hi && c.low == lo && (hi == lo || c.suited == suited)) return i;
    }
    return 0;
}

